fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let ly: i32 = 40;
    let lh: i32 = h - 80;
    let rowh: i32 = lh / 8;
    let total: i32 = 24;
    let sbx: i32 = w - 40;
    let mut off: i32 = host::display::state_get(0);
    if down == 1 && px >= sbx - 10 {
        let mut rel: i32 = (py - ly) * (total - 8) / lh;
        if rel < 0 { rel = 0; }
        if rel > total - 8 { rel = total - 8; }
        off = rel;
        host::display::state_set(0, off);
    }
    host::display::clear(0x101010);
    host::display::draw_string(30, 16, "DRAG THE SCROLLBAR", 0x808080, 1);
    let mut i: i32 = 0;
    while i < 8 {
        let ry: i32 = ly + i * rowh;
        let n: i32 = off + i;
        let mut rc: i32 = 0x181818;
        if n % 2 == 0 { rc = 0x222222; }
        host::display::fill_rect(30, ry, sbx - 50, rowh - 2, rc);
        host::display::draw_string(40, ry + rowh / 2 - 4, "ITEM", 0x808080, 1);
        host::display::draw_number(80, ry + rowh / 2 - 4, n, 0xffffff, 1);
        i = i + 1;
    }
    host::display::fill_rect(sbx, ly, 12, lh, 0x282828);
    let th: i32 = lh * 8 / total;
    let toff: i32 = off * (lh - th) / (total - 8);
    host::display::fill_rect(sbx, ly + toff, 12, th, 0x808080);
    host::display::present();
}
